import{_ as l,o as a,c,ag as e}from"./chunks/framework.FZrpoovI.js";const u=JSON.parse('{"title":"Color 色彩","description":"","frontmatter":{},"headers":[],"relativePath":"guide/color.md","filePath":"guide/color.md","lastUpdated":1785404608000}'),r={name:"guide/color.md"};function s(t,o,d,i,p,n){return a(),c("div",null,[...o[0]||(o[0]=[e('<h1 id="color-色彩" tabindex="-1">Color 色彩 <a class="header-anchor" href="#color-色彩" aria-label="Permalink to &quot;Color 色彩&quot;">​</a></h1><hr><p>统一的色彩搭配可以提高品牌的识别度，色彩的运用除了需要考虑品牌的统一性之外，还需要达到信息传递，交互反馈等目的。<code>Taro UI</code> 是凹凸实验室出品，品牌颜色为「凹凸蓝」，因此 <code>Taro UI</code> 的整体配色风格也是基于「凹凸蓝」展开的。</p><h2 id="主色" tabindex="-1">主色 <a class="header-anchor" href="#主色" aria-label="Permalink to &quot;主色&quot;">​</a></h2><p>用于标识品牌颜色</p><div class="color-palette"><div class="color-item" style="background-color:#6190E8;"><p class="color-name">Brand Color</p><p class="color-value">#6190E8</p></div></div><h2 id="辅助色" tabindex="-1">辅助色 <a class="header-anchor" href="#辅助色" aria-label="Permalink to &quot;辅助色&quot;">​</a></h2><p>用于标识状态的按钮等</p><div class="color-palette"><div class="color-item" style="background-color:#13CE66;"><p class="color-name">Green - Positive</p><p class="color-value">#13CE66</p></div><div class="color-item" style="background-color:#FF4949;"><p class="color-name">Red - Negative</p><p class="color-value">#FF4949</p></div><div class="color-item dark-text" style="background-color:#FFC82C;"><p class="color-name">Yellow - Warning</p><p class="color-value">#FFC82C</p></div><div class="color-item" style="background-color:#78A4FA;"><p class="color-name">Blue - Info</p><p class="color-value">#78A4FA</p></div></div><h2 id="次辅助色" tabindex="-1">次辅助色 <a class="header-anchor" href="#次辅助色" aria-label="Permalink to &quot;次辅助色&quot;">​</a></h2><p>用于不那么重要的信息等</p><div class="color-palette"><div class="color-item" style="background-color:#C2ABC7;"><p class="color-name">Roof</p><p class="color-value">#C2ABC7</p></div><div class="color-item dark-text" style="background-color:#F0D0D5;"><p class="color-name">Curtain</p><p class="color-value">#F0D0D5</p></div><div class="color-item dark-text" style="background-color:#F1E4ED;"><p class="color-name">Door</p><p class="color-value">#F1E4ED</p></div><div class="color-item dark-text" style="background-color:#EEF0F0;"><p class="color-name">Wall</p><p class="color-value">#EEF0F0</p></div></div><h2 id="中性色" tabindex="-1">中性色 <a class="header-anchor" href="#中性色" aria-label="Permalink to &quot;中性色&quot;">​</a></h2><p>用于文本、背景和边框</p><div class="color-palette"><div class="color-item" style="background-color:#2C405A;"><p class="color-name">Header 标题</p><p class="color-value">#2C405A</p></div><div class="color-item" style="background-color:#3F536E;"><p class="color-name">正文字体 - 黑</p><p class="color-value">#3F536E</p></div><div class="color-item" style="background-color:#8DABC4;"><p class="color-name">正文字体 - 灰</p><p class="color-value">#8DABC4</p></div><div class="color-item" style="background-color:#A8C6DF;"><p class="color-name">图标</p><p class="color-value">#A8C6DF</p></div><div class="color-item" style="background-color:#C5D9E8;"><p class="color-name">边框</p><p class="color-value">#C5D9E8</p></div><div class="color-item dark-text" style="background-color:#ECF5FD;"><p class="color-name">背景色 - 浅蓝</p><p class="color-value">#ECF5FD</p></div><div class="color-item dark-text" style="background-color:#FAFBFC;"><p class="color-name">背景色 - 米白</p><p class="color-value">#FAFBFC</p></div></div>',15)])])}const m=l(r,[["render",s]]);export{u as __pageData,m as default};
